1	/**
2	 * Chase Bank Authentication Utilities
3	 * 
4	 * Manages cookie storage and session persistence.
5	 */
6	
7	import * as fs from "fs";
8	import * as path from "path";
9	import * as os from "os";
10	import { BrowserContext } from "patchright";
11	
12	const COOKIES_DIR = path.join(os.homedir(), ".strider", "chase");
13	const COOKIES_PATH = path.join(COOKIES_DIR, "cookies.json");
14	
15	export interface AuthState {
16	  isLoggedIn: boolean;
17	  accountHolder?: string;
18	}
19	
20	/**
21	 * Get the path to the cookies file
22	 */
23	export function getCookiesPath(): string {
24	  return COOKIES_PATH;
25	}
26	
27	/**
28	 * Check if cookies file exists
29	 */
30	export function hasStoredCookies(): boolean {
31	  return fs.existsSync(COOKIES_PATH);
32	}
33	
34	/**
35	 * Save cookies to disk
36	 */
37	export async function saveCookies(context: BrowserContext): Promise<void> {
38	  try {
39	    if (!fs.existsSync(COOKIES_DIR)) {
40	      fs.mkdirSync(COOKIES_DIR, { recursive: true });
41	    }
42	    const cookies = await context.cookies();
43	    fs.writeFileSync(COOKIES_PATH, JSON.stringify(cookies, null, 2));
44	  } catch (error) {
45	    console.error("Failed to save cookies:", error);
46	  }
47	}
48	
49	/**
50	 * Load cookies from disk into context
51	 */
52	export async function loadCookies(context: BrowserContext): Promise<void> {
53	  try {
54	    if (fs.existsSync(COOKIES_PATH)) {
55	      const cookies = JSON.parse(fs.readFileSync(COOKIES_PATH, "utf-8"));
56	      await context.addCookies(cookies);
57	    }
58	  } catch (error) {
59	    console.error("Failed to load cookies:", error);
60	  }
61	}
62	
63	/**
64	 * Clear stored cookies
65	 */
66	export function clearCookies(): void {
67	  try {
68	    if (fs.existsSync(COOKIES_PATH)) {
69	      fs.unlinkSync(COOKIES_PATH);
70	    }
71	  } catch (error) {
72	    console.error("Failed to clear cookies:", error);
73	  }
74	}
75	
76	/**
77	 * Get current auth state
78	 */
79	export function getAuthState(): AuthState {
80	  return {
81	    isLoggedIn: hasStoredCookies(),
82	  };
83	}
