7	import { chromium, Browser, BrowserContext, Page } from "patchright";
8	import { saveCookies, loadCookies, AuthState } from "./auth.js";
9	
10	const CHASE_BASE_URL = "https://www.chase.com";
11	const DEFAULT_TIMEOUT = 60000;
12	
13	// Singleton browser instance
14	let browser: Browser | null = null;
15	let context: BrowserContext | null = null;
16	let page: Page | null = null;
17	
18	export interface Account {
19	  id: string;
20	  name: string;
21	  type: "checking" | "savings" | "credit" | "investment" | "loan";
22	  balance: number;
23	  availableBalance?: number;
24	  accountNumber?: string;
25	  lastFour?: string;
26	}
27	
28	export interface Transaction {
29	  id: string;
30	  date: string;
31	  description: string;
32	  amount: number;
33	  type: "credit" | "debit";
34	  category?: string;
35	  pending: boolean;
36	  merchant?: string;
37	}
38	
39	export interface Bill {
40	  id: string;
41	  payee: string;
42	  amount: number;
43	  dueDate: string;
44	  status: "scheduled" | "paid" | "overdue";
45	  autopay: boolean;
46	}
