128	/**
129	 * Get Chase login URL and instructions
130	 */
131	export async function getLoginUrl(): Promise<{ url: string; instructions: string }> {
132	  return {
133	    url: "https://secure.chase.com/web/auth/dashboard",
134	    instructions:
135	      "Please log in to Chase in a browser, then export your cookies to ~/.strider/chase/cookies.json. Use a browser extension like 'Cookie-Editor' to export cookies in JSON format. Note: Chase uses MFA, so you may need to re-export cookies after each session.",
136	  };
137	}
