139	/**
140	 * Check authentication status
141	 */
142	export async function checkAuth(): Promise<AuthState> {
143	  try {
144	    const p = await getPage();
145	    await p.goto(`${CHASE_BASE_URL}/web/auth/dashboard`, { waitUntil: "networkidle" });
146	    
147	    // Check if we're on the dashboard or redirected to login
148	    const currentUrl = p.url();
149	    
150	    if (currentUrl.includes("/auth/logon") || currentUrl.includes("/login")) {
151	      return { isLoggedIn: false };
152	    }
153	    
154	    // Try to get account holder name
155	    const holderName = await p.$eval(
156	      '.mds-header-user-name, .account-holder-name, [data-testid="user-greeting"]',
157	      (el) => el.textContent?.trim() || "",
158	    ).catch(() => "");
159	    
160	    return {
161	      isLoggedIn: true,
162	      accountHolder: holderName || undefined,
163	    };
164	  } catch (error) {
165	    return { isLoggedIn: false };
166	  }
167	}
168	
169	/**
170	 * Get all accounts
171	 */
172	export async function getAccounts(): Promise<{ success: boolean; accounts?: Account[]; error?: string }> {
173	  try {
174	    const p = await getPage();
175	    await p.goto(`${CHASE_BASE_URL}/web/auth/dashboard`, { waitUntil: "networkidle" });
176	    
177	    await p.waitForTimeout(2000);
178	    
179	    const accounts = await p.$$eval(
180	      '.account-tile, .account-card, [data-testid="account-tile"]',
181	      (elements) =>
182	        elements.map((el, index) => {
183	          const nameEl = el.querySelector('.account-name, .tile-header, h3');
184	          const balanceEl = el.querySelector('.account-balance, .balance, [data-testid="balance"]');
185	          const lastFourEl = el.querySelector('.account-last-four, .masked-number');
186	          const typeEl = el.querySelector('.account-type');
187	          
188	          const name = nameEl?.textContent?.trim() || `Account ${index + 1}`;
189	          const balanceText = balanceEl?.textContent?.trim() || '0';
190	          const balance = parseFloat(balanceText.replace(/[$,]/g, '')) || 0;
191	          const lastFour = lastFourEl?.textContent?.trim().replace(/[^0-9]/g, '').slice(-4) || undefined;
192	          
193	          let type: 'checking' | 'savings' | 'credit' | 'investment' | 'loan' = 'checking';
194	          const typeText = (typeEl?.textContent || name).toLowerCase();
195	          if (typeText.includes('saving')) type = 'savings';
196	          else if (typeText.includes('credit') || typeText.includes('card')) type = 'credit';
197	          else if (typeText.includes('invest') || typeText.includes('brokerage')) type = 'investment';
198	          else if (typeText.includes('loan') || typeText.includes('mortgage') || typeText.includes('auto')) type = 'loan';
199	          
200	          return {
201	            id: el.getAttribute('data-account-id') || `account-${index}`,
202	            name,
203	            type,
204	            balance,
205	            lastFour,
206	          };
207	        }),
208	    );
209	    
210	    return { success: true, accounts };
211	  } catch (error) {
212	    return {
213	      success: false,
214	      error: error instanceof Error ? error.message : "Failed to get accounts",
215	    };
216	  }
217	}
