219	/**
220	 * Get account transactions
221	 */
222	export async function getTransactions(
223	  accountId: string,
224	  limit: number = 25
225	): Promise<{ success: boolean; transactions?: Transaction[]; error?: string }> {
226	  try {
227	    const p = await getPage();
228	    
229	    // Navigate to account details
230	    await p.goto(`${CHASE_BASE_URL}/web/auth/dashboard`, { waitUntil: "networkidle" });
231	    await p.waitForTimeout(1000);
232	    
233	    // Click on the account
234	    const accountTile = await p.$(`[data-account-id="${accountId}"], .account-tile:nth-child(${parseInt(accountId.replace('account-', '')) + 1})`);
235	    if (accountTile) {
236	      await accountTile.click();
237	      await p.waitForNavigation({ waitUntil: "networkidle" }).catch(() => {});
238	    }
239	    
240	    await p.waitForTimeout(2000);
241	    
242	    const transactions = await p.$$eval(
243	      '.transaction-row, .activity-row, [data-testid="transaction"]',
244	      (elements, maxItems) =>
245	        elements.slice(0, maxItems).map((el, index) => {
246	          const dateEl = el.querySelector('.transaction-date, .date, td:first-child');
247	          const descEl = el.querySelector('.transaction-description, .description, .merchant-name');
248	          const amountEl = el.querySelector('.transaction-amount, .amount');
249	          const pendingEl = el.querySelector('.pending, .pending-badge');
