"""Encryption for access tokens at rest (Fernet, key from .env)."""
import os
from cryptography.fernet import Fernet

_key = os.environ.get("FERNET_KEY")
if not _key:
    raise RuntimeError(
        "FERNET_KEY missing. Generate one with:\n"
        '  python3 -c "from cryptography.fernet import Fernet; print(Fernet.generate_key().decode())"\n'
        "and put it in .env"
    )

_fernet = Fernet(_key.encode())


def encrypt(plaintext: str) -> str:
    return _fernet.encrypt(plaintext.encode()).decode()


def decrypt(ciphertext: str) -> str:
    return _fernet.decrypt(ciphertext.encode()).decode()

"""Envelope Budget — Phase 0: connect two banks via Plaid and merge into one feed.

Run:  python3 app.py   (binds to 127.0.0.1:5010 only)
"""
import os

from dotenv import load_dotenv

load_dotenv()  # must run before importing modules that read env at import time

from flask import Flask, jsonify, render_template, request

import db
import plaid_client as plaid_api
from crypto import decrypt, encrypt

app = Flask(__name__)


def _normalize_txn(t):
    """Plaid transaction dict -> our transactions row dict."""
    pfc = t.get("personal_finance_category") or {}
    return {
        "txn_id": t["transaction_id"],
        "account_id": t["account_id"],
        "date": str(t.get("date") or ""),
        "name": t.get("name") or "",
        "merchant": t.get("merchant_name"),
        "amount": t.get("amount"),
        "currency": t.get("iso_currency_code") or t.get("unofficial_currency_code"),
        "pending": 1 if t.get("pending") else 0,
        "category": pfc.get("primary"),
    }


@app.route("/")
def index():
    return render_template("index.html")


@app.route("/api/create_link_token", methods=["POST"])
def create_link_token():
    return jsonify({"link_token": plaid_api.create_link_token()})


@app.route("/api/exchange_public_token", methods=["POST"])
def exchange_public_token():
    body = request.get_json(force=True)
    public_token = body["public_token"]
    institution = body.get("institution") or "Unknown"

    access_token, item_id = plaid_api.exchange_public_token(public_token)
    db.upsert_item(item_id, institution, encrypt(access_token))

    # Pull account metadata so the feed can label rows.
    for a in plaid_api.get_accounts(access_token):
        db.upsert_account(
            a["account_id"], item_id, a.get("name"), a.get("mask"),
            str(a.get("type") or ""), str(a.get("subtype") or ""),
        )

    return jsonify({"ok": True, "item_id": item_id, "institution": institution})


@app.route("/api/sync", methods=["POST"])
def sync():
    """Sync every connected item, then return the merged feed."""
    for item in db.get_items():
        access_token = decrypt(item["access_token_enc"])
        added, modified, removed, cursor = plaid_api.sync_transactions(
            access_token, item["sync_cursor"]
        )
        for t in added + modified:
            db.upsert_transaction(_normalize_txn(t))
        for t in removed:
            db.delete_transaction(t["transaction_id"])
        db.set_cursor(item["item_id"], cursor)

    return jsonify({"feed": db.get_feed()})


@app.route("/api/feed")
def feed():
    return jsonify({"feed": db.get_feed()})


@app.route("/api/items")
def items():
    return jsonify({
        "items": [
            {"item_id": i["item_id"], "institution": i["institution"]}
            for i in db.get_items()
        ]
    })


if __name__ == "__main__":
    db.init_db()
    port = int(os.environ.get("PORT", 5010))
    # Localhost only — never expose banking data on the network.
    app.run(host="127.0.0.1", port=port, debug=False)

