"""Envelope budgeting logic on top of the ledger (Phase 2 + 3).

Sign convention: Plaid `amount` is positive for outflows (money leaving the
account) and negative for inflows. Ledger rows store cents that move a bucket up
(+) or down (-), so we negate Plaid's amount.

Credit-card handling (the YNAB method):
  - Charging the card drains its spending envelope AND reserves the same amount
    in the card's Payment envelope -> net zero to your cash, because a credit
    charge doesn't move real money yet, it just earmarks it.
  - Paying the card (checking -> card) is one money movement shown as two
    transactions. We mark both as transfers (excluded from spending) and drain
    the Payment envelope -> that's when the cash actually leaves.
"""
import db

# Plaid personal_finance_category primaries that signal a transfer rather than spend.
CC_PAYMENT_CATEGORIES = {"LOAN_PAYMENTS", "TRANSFER_OUT"}
TRANSFER_IN_CATEGORIES = {"TRANSFER_IN"}


def _cents(amount):
    return round(amount * 100)


def match_rule(txn):
    name = (txn["name"] or "").lower()
    merchant = (txn["merchant"] or "").lower()
    category = (txn["category"] or "")
    for r in db.list_rules():
        p, mt = r["pattern"], r["match_type"]
        if mt == "category" and category == p:
            return r["envelope_id"]
        if mt == "merchant_contains" and p.lower() in merchant:
            return r["envelope_id"]
        if mt == "name_contains" and p.lower() in name:
            return r["envelope_id"]
    return None


def _book_card_spend(txn_id, account_id, envelope_id, cents):
    """Charge on a credit card: drain the spending envelope, reserve the payment."""
    db.add_ledger(envelope_id, txn_id, -cents, "spend")        # cents>0 -> drains envelope
    pay_env = db.get_or_create_payment_envelope(account_id)
    db.add_ledger(pay_env, txn_id, cents, "cc_reserve")        # set aside to pay the card


def classify_new():
    """Auto-book transactions with no ledger row yet."""
    classified = 0
    for t in db.transactions_without_ledger():
        amt, cents, cat = t["amount"], _cents(t["amount"]), (t["category"] or "")
        acct_type = t["account_type"]

        if acct_type == "credit":
            if amt < 0:
                # Inflow to a card = payment (or refund). Net it out and drain the
                # card's Payment envelope. (A refund can be reclassified by hand.)
                db.set_transfer(t["txn_id"], True)
                pay_env = db.get_or_create_payment_envelope(t["account_id"])
                db.add_ledger(pay_env, t["txn_id"], cents, "cc_payment")  # cents<0 -> drains
                classified += 1
            else:
                env = match_rule(t)
                if env is not None:
                    _book_card_spend(t["txn_id"], t["account_id"], env, cents)
                    classified += 1
                # uncategorized charge: leave for manual assignment
        else:  # depository
            if amt > 0:
                # Outflow. A credit-card payment or internal transfer is netted out;
                # the card side already moved the envelope, so don't double-count.
                if cat in CC_PAYMENT_CATEGORIES or db.find_card_payment_match(cents, t["date"]):
                    db.set_transfer(t["txn_id"], True)
                    classified += 1
                else:
                    env = match_rule(t)
                    if env is not None:
                        db.add_ledger(env, t["txn_id"], -cents, "spend")
                        classified += 1
            else:
                # Inflow. Income, unless it's an internal transfer in.
                if cat in TRANSFER_IN_CATEGORIES:
                    db.set_transfer(t["txn_id"], True)
                else:
                    db.add_ledger(None, t["txn_id"], -cents, "income")  # -cents>0 -> RTA
                classified += 1
    return classified


def assign_txn(txn_id, target):
    """Manually (re)assign a transaction.

    target: envelope id | "income" | "transfer" | "unassign".
    """
    txn = db.get_txn(txn_id)
    if txn is None:
        raise ValueError(f"Unknown transaction: {txn_id}")
    db.clear_txn_ledger(txn_id)
    amt, cents = txn["amount"], _cents(txn["amount"])

    if target == "unassign":
        db.set_transfer(txn_id, False)
        return
    if target == "transfer":
        db.set_transfer(txn_id, True)
        # Draining the Payment envelope only makes sense for the card-side credit.
        if txn["account_type"] == "credit" and amt < 0:
            pay_env = db.get_or_create_payment_envelope(txn["account_id"])
            db.add_ledger(pay_env, txn_id, cents, "cc_payment")
        return

    db.set_transfer(txn_id, False)
    if target == "income":
        db.add_ledger(None, txn_id, -cents, "income")
        return

    env_id = int(target)
    if txn["account_type"] == "credit" and amt > 0:
        _book_card_spend(txn_id, txn["account_id"], env_id, cents)
    else:
        db.add_ledger(env_id, txn_id, -cents, "spend")


def fund_envelope(envelope_id, amount_cents):
    """Move money from Ready to Assign into an envelope (two ledger rows)."""
    if amount_cents <= 0:
        return
    db.add_ledger(None, None, -amount_cents, "fund")
    db.add_ledger(envelope_id, None, amount_cents, "fund")


def fund_to_targets():
    """Top each envelope up to its monthly target, in order, until RTA runs out."""
    rta = db.ready_to_assign_cents()
    funded = 0
    for e in db.list_envelopes():
        if rta <= 0:
            break
        gap = e["target_cents"] - e["available_cents"]
        if gap > 0:
            amount = min(gap, rta)
            fund_envelope(e["id"], amount)
            rta -= amount
            funded += amount
    return funded

