def match_single(rule, txn):
    p, mt = rule["pattern"], rule["match_type"]
    if mt == "category":
        return (txn["category"] or "") == p
    if mt == "merchant_contains":
        return p.lower() in (txn["merchant"] or "").lower()
    if mt == "name_contains":
        return p.lower() in (txn["name"] or "").lower()
    return False


def match_rule(txn):
    """First rule that matches -> its envelope id, else None."""
    for r in db.list_rules():
        if match_single(r, txn):
            return r["envelope_id"]
    return None


def _apply_spend(txn, envelope_id):
    """Book a spend assignment (with credit-card reserve). Caller clears the ledger first."""
    cents = _cents(txn["amount"])
    if txn["account_type"] == "credit" and txn["amount"] > 0:
        _book_card_spend(txn["txn_id"], txn["account_id"], envelope_id, cents)
    else:
        db.add_ledger(envelope_id, txn["txn_id"], -cents, "spend")


def apply_rule(rule):
    """(Re)assign every existing matching outflow that isn't a transfer or hand-picked.
    Returns the number of transactions affected."""
    count = 0
    for t in db.transactions_for_rule_scan():
        if match_single(rule, t):
            db.clear_txn_ledger(t["txn_id"])
            _apply_spend(t, rule["envelope_id"])
            count += 1
    return count

