  statusTimer = setTimeout(() => el.classList.remove("show"), 3500);
}

window.delRule = async (id) => { await post(`/api/rules/${id}/delete`); loadBudget(); };
window.alwaysRule = async (txnId) => {
  const t = FEEDMAP[txnId];
  if (!t || t.assigned_envelope_id == null) return;
  const useMerchant = !!(t.merchant && t.merchant.trim());
  const match_type = useMerchant ? "merchant_contains" : "name_contains";
  const pattern = (useMerchant ? t.merchant : t.name).trim();
  const env = ENVS.find(e => e.id === t.assigned_envelope_id);
  const r = await post("/api/rules", { match_type, pattern, envelope_id: t.assigned_envelope_id });
  flash(`Always: “${pattern}” → ${env ? env.name : "bucket"}. Also applied to ${r.applied} other match(es).`);
  refreshAll();
};

